package com.diamonddagger590.mccore.external.common;

import com.diamonddagger590.mccore.util.item.CustomItemWrapper;
import org.bukkit.Material;
import org.bukkit.inventory.ItemStack;
import org.jetbrains.annotations.NotNull;

import java.util.Arrays;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Collectors;

/**
 * A type of {@link com.diamonddagger590.mccore.registry.plugin.PluginHook} which supports custom item models.
 */
public interface CustomItemHook {

    /**
     * Checks to see if the provided item model is a valid custom model.
     *
     * @param itemName The model name to check.
     * @return {@code true} if the provided item model is a valid custom model.
     */
    boolean isItem(@NotNull String itemName);

    /**
     * Checks to see if the provided {@link ItemStack} has a custom model on it.
     *
     * @param itemStack The item stack to check.
     * @return {@code true} if the provided {@link ItemStack} has a custom model on it.
     */
    boolean isItem(@NotNull ItemStack itemStack);

    /**
     * Checks to see if the provided {@link CustomItemWrapper} is an instance of a custom item.
     *
     * @param customMaterial The wrapper to check.
     * @return {@code true} if the provided {@link CustomItemWrapper} is an instance of a custom item.
     */
    default boolean isItem(@NotNull CustomItemWrapper customMaterial) {
        return customMaterial.customItem().map(this::isItem).orElse(false);
    }

    /**
     * Checks to see if the provided {@link ItemStack} has the specified model on it.
     *
     * @param itemStack The item stack to check.
     * @param itemName  The custom model to check.
     * @return {@code true} if the provided {@link ItemStack} has the specified model on it.
     */
    boolean isItemOfType(@NotNull ItemStack itemStack, @NotNull String itemName);

    /**
     * Gets an {@link Optional} containing the custom {@link ItemStack} generated by the provided model name.
     *
     * @param itemName The custom model name to use.
     * @return An {@link Optional} containing the custom {@link ItemStack} generated by the provided model name.
     * This optional will be empty if no plugin supports the provided model name.
     */
    @NotNull
    Optional<ItemStack> item(@NotNull String itemName);

    /**
     * Gets an {@link Optional} containing all the models that the provided {@link ItemStack} has on it.
     *
     * @param itemStack The item stack to get the models from.
     * @return An {@link Optional} containing all the models that the provided {@link ItemStack} has on it. This
     * optional will be empty if there are no models on the item stack.
     */
    @NotNull
    Optional<Set<String>> itemModels(@NotNull ItemStack itemStack);

    /**
     * Gets the name to use to represent the {@link CustomItemWrapper}.
     *
     * @param customItemWrapper The {@link CustomItemWrapper} to get the name of.
     * @return The name to use to represent the {@link CustomItemWrapper}.
     */
    @NotNull
    String itemName(@NotNull CustomItemWrapper customItemWrapper);
}
